package access

// Viewer is the per-request authority scope every content read is gated by
// (l6-accounts D2/D4). It is a pure VALUE: pass it, copy it, store it — a
// Viewer never aliases caller-held memory (the constructors copy their
// slice/map inputs) and mutating a held Viewer never affects anyone else.
//
// The zero Viewer hides EVERYTHING (fail closed): no Admin flag, no visible
// set — the store's visibility fragment collapses it to `1=0`. Unrestricted
// scope is always an explicit, constructed decision, never an absence.
type Viewer struct {
	// Admin marks an UNRESTRICTED (see-all) scope: the System, Admin, and
	// LegacyDevice scopes all carry it, which is what the store's visibility
	// fragment keys on ("" clause, byte-identical SQL to pre-accounts). A
	// User scope and the zero value carry it false — their reads are
	// narrowed to UserID's visible set.
	Admin bool

	// UserID is the acting user's row id; 0 for the non-user scopes
	// (System, Admin, LegacyDevice) and for the zero Viewer. Ledger writes
	// stamp this id — 0 is the legacy slot (l6-accounts D7).
	UserID int64

	// VisibleLibraryIDs is the union of the user's groups' member
	// Collections, intersected live with the libraries table at resolution
	// time (identity.ResolveViewer, D5). Both consumers read the same set:
	// the store's SQL IN-list fragment and Go-side paging (browse-scale).
	// An empty set narrows every read to nothing — fail closed.
	VisibleLibraryIDs []int64

	// ChainMutes is the user's groups' per-source mutes merged MUTE-WINS
	// (D8), keyed by plugin id: true = the source is muted for this viewer.
	// Applied read-time only, as a post-ResolveGates AND-down on copies —
	// never at write time, never as synthetic pref rows.
	ChainMutes map[string]bool
}

// System is the internal trusted scope: write-time reads, learning and boot
// backfill, queue/scan/janitor gates. It sees everything and stamps the
// legacy slot (UserID 0). Every non-request entry point into the gated reads
// constructs it explicitly — the compiler-forced sweep is the point (D2).
func System() Viewer { return Viewer{Admin: true} }

// Admin is the authenticated human administrator scope (env admin token and
// admin-role users alike — D1): see-all, ledger slot 0.
func Admin() Viewer { return Viewer{Admin: true} }

// User is a scoped user principal: it sees exactly the visible-library set
// passed in (empty set = sees nothing) with the group chain mutes applied.
// The inputs are COPIED — the caller keeps ownership and may mutate its
// slice/map afterwards without touching the Viewer (copy-on-read contract).
func User(userID int64, visibleLibraryIDs []int64, chainMutes map[string]bool) Viewer {
	ids := make([]int64, len(visibleLibraryIDs))
	copy(ids, visibleLibraryIDs)
	mutes := make(map[string]bool, len(chainMutes))
	for pluginID, muted := range chainMutes {
		mutes[pluginID] = muted
	}
	return Viewer{
		UserID:            userID,
		VisibleLibraryIDs: ids,
		ChainMutes:        mutes,
	}
}

// LegacyDevice is the unbound-device scope — today's see-all posture
// (D1 documented residual until the restricted-library floor lands). It is
// deliberately NOT the zero Viewer: an unbound device is an explicit
// see-all principal, while the zero Viewer fails closed.
func LegacyDevice() Viewer { return Viewer{Admin: true} }
